css:
.content.p39-page { --p39-pad-x: var(--s-3); --p39-pad-y: var(--s-3); padding: var(--p39-pad-y) var(--p39-pad-x); min-height: 100%; display: flex; flex-direction: column; gap: var(--s-4); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .content.p39-page { --p39-pad-x: var(--s-5); --p39-pad-y: var(--s-4); } }
.p39-foot { position: sticky; bottom: 0; z-index: 1; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2); margin: auto calc(var(--p39-pad-x) * -1) calc(var(--p39-pad-y) * -1); padding: var(--s-3) var(--p39-pad-x); background: var(--white); border-top: var(--w1) solid var(--rule); }
.p39-col { display: grid; gap: var(--s-4); width: 100%; max-width: 56rem; align-content: start; }
.p39-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s-2) var(--s-3); }
.p39-titlerow { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s-2) var(--s-3); width: 100%; }
.p39-state { display: flex; align-items: center; gap: var(--s-3); padding-block: var(--s-3); }
.p39-err { --frame-w: var(--w2); }

.p39-ev { grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "body chev" "actions actions"; }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p39-ev { grid-template-columns: minmax(0, 1fr) auto auto; grid-template-areas: "body value chev"; } }
.p39-chev { grid-area: chev; width: var(--hit); height: var(--hit); min-width: var(--hit); min-height: var(--hit); align-self: center; }

.p39-up { position: sticky; bottom: 5.5rem; align-self: flex-end; z-index: 2; width: 2.75rem; height: 2.75rem; min-width: 2.75rem; min-height: 2.75rem; margin-top: calc(-2.75rem - var(--s-4)); }
.p39-wrapbtn { flex-wrap: wrap; }
.p39-wrapbtn .banner__text { flex: 1 1 14rem; }
.input.p39-focus { border: var(--w2) solid var(--blue); padding-inline: calc(var(--s-3) - var(--w1)); }
.p39-note { display: grid; gap: var(--s-2); justify-items: start; }

.p39-filter { display: grid; gap: var(--s-1); }
.p39-checks { display: grid; gap: 0; }
.p39-list { display: grid; gap: var(--s-2); margin: 0; padding: 0; }
.p39-act { margin-top: var(--s-2); }
.p39-empty { display: grid; gap: var(--s-1); padding: var(--s-4) var(--s-3); max-width: var(--measure); }
.p39-empty p { margin: 0; }
.p39-more { display: flex; align-items: center; gap: var(--s-3); justify-content: center; padding-block: var(--s-3); }
.p39-end { text-align: center; padding-block: var(--s-3); }
.p39-ev .rec__lead { align-self: start; }
.p39-time { color: var(--muted); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p39-shift .p39-col { margin-top: calc(var(--p39-shift, 0rem) * -1); } }
